/**
 *
 * MenuSubmenuTrigger is a component that displays the trigger for a submenu item.
 *
 * [Live Demo](https://www.primereact.org/menu/)
 *
 * @module MenuSubmenuTrigger
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { MenuPortalInstance } from './MenuPortal.types';
import type { MenuRootInstance } from './MenuRoot.types';
import type { MenuSubmenuInstance } from './MenuSubmenu.types';
/**
 * Defines passthrough(pt) options type in MenuSubmenuTrigger component.
 */
export type MenuSubmenuTriggerPassThroughType<E> = PassThroughType<MenuSubmenuTriggerInstance, E>;
/**
 * Defines passthrough(pt) options of MenuSubmenuTrigger component.
 */
export interface MenuSubmenuTriggerPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: MenuSubmenuTriggerPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in MenuSubmenuTrigger component.
 */
export interface MenuSubmenuTriggerProps extends BaseComponentProps<MenuSubmenuTriggerInstance, unknown, MenuSubmenuTriggerPassThrough> {
    /**
     * Semantic value that uniquely identifies this submenu trigger within the
     * outer menu. Used to generate a deterministic DOM id; auto-generated when
     * not provided.
     */
    value?: string;
}
/**
 * Defines valid state in MenuSubmenuTrigger component.
 */
export interface MenuSubmenuTriggerState {
}
/**
 * Defines the methods and properties exposed by MenuSubmenuTrigger component.
 */
export interface MenuSubmenuTriggerExposes {
    /**
     * Instance of the Menu component.
     */
    menu: MenuRootInstance | undefined | null;
    /**
     * Instance of the MenuSubmenu component.
     */
    submenu: MenuSubmenuInstance | undefined | null;
    /**
     * Instance of the MenuPortal component.
     */
    portal: MenuPortalInstance | undefined | null;
    /**
     * Identifier of the menu item.
     */
    itemId: string | undefined;
    /**
     * Whether the menu item is focused.
     */
    focused: boolean;
    /**
     * Whether the menu item is disabled.
     */
    isDisabled: boolean;
}
/**
 * Instance of MenuSubmenuTrigger component.
 */
export type MenuSubmenuTriggerInstance = ComponentInstance<MenuSubmenuTriggerProps, MenuSubmenuTriggerState, MenuSubmenuTriggerExposes>;
